package top.niunaijun.blackbox.widget;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

public final class CatEngineLogoData {
    private static Bitmap sCachedBitmap = null;
    private static final String LOGO_PNG_BASE64 = "";

    public static synchronized Bitmap getLogoBitmap() {
        if (sCachedBitmap != null && !sCachedBitmap.isRecycled()) {
            return sCachedBitmap;
        }
        try {
            byte[] bytes = Base64.decode(LOGO_PNG_BASE64, Base64.DEFAULT);
            sCachedBitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
        } catch (Throwable ignored) {}
        return sCachedBitmap;
    }
}
